<section class="settings-section" aria-labelledby="preferences-heading">
    <div class="section-intro"><h2 id="preferences-heading">Appearance</h2><p>Saved on this device. Changes apply immediately.</p></div>
    <div class="form-stack form-width">
        <fieldset class="theme-fieldset"><legend>Color theme</legend><div class="theme-options">
            <label class="theme-option"><input type="radio" name="color-theme" value="light" data-theme-input><span class="theme-preview preview-light"><i></i><i></i><i></i></span><span>Light</span></label>
            <label class="theme-option"><input type="radio" name="color-theme" value="dark" data-theme-input><span class="theme-preview preview-dark"><i></i><i></i><i></i></span><span>Dark</span></label>
            <label class="theme-option"><input type="radio" name="color-theme" value="system" data-theme-input><span class="theme-preview preview-system"><i></i><i></i><i></i></span><span>System</span></label>
        </div></fieldset>
        <div class="form-grid"><div class="field"><label for="number-format">Numbers</label><select id="number-format" data-number-preference><option value="full">Full numbers · 12,450</option><option value="compact">Compact · 12.5K</option></select></div><div class="field"><label for="density">Overview spacing</label><select id="density" data-density-preference><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></div></div>
        <p class="field-hint">Metric tables always show exact values. Chart dates use each source’s reporting timezone.</p>
        <p class="sr-only" aria-live="polite" data-preference-status></p>
    </div>
</section>
